"""A chart of a metric the shown runs have not logged yet is drawn empty, not as an error (the autogenerated KeyError 'step')."""

from __future__ import annotations

import pandas as pd

from dlboard.conftest import panel_data_of
from dlboard.models._view import ChartInstance
from dlboard.plugins.charts.line_chart import LineChart

LineChart.register(allow_override=True)


def test_a_line_chart_of_a_metric_no_shown_run_logged_renders_empty() -> None:
    # The newest run is drawn and is still training: it has logged `train/loss`, not `val/loss`, which an older
    # run that is not drawn did log. The autogenerated chart of `val/loss` is handed nothing to draw.
    newest_run = pd.DataFrame({"run_id": [2, 2], "step": [0, 1], "train/loss": [1.0, 0.5]})
    chart = ChartInstance[pd.DataFrame, object](
        chart_type=LineChart.name, parameters={"column": "val/loss", "x_axis": "step"}
    )

    frame = panel_data_of(newest_run).for_chart(chart)

    assert frame.empty
    chart.render(frame)
